class Solution:
    def largestDivisibleSubset(self, nums: list[int]) -> list[int]:
        arr = sorted(nums)
        chains = []
        best = []
        for x in arr:
            cur = [x]
            for chain in chains:
                if x % chain[-1] == 0:
                    cand = chain + [x]
                    if len(cand) > len(cur) or (len(cand) == len(cur) and cand < cur):
                        cur = cand
            chains.append(cur)
            if len(cur) > len(best) or (len(cur) == len(best) and cur < best):
                best = cur
        return best

